import os
import json
from typing import Optional

from google.cloud import kms_v1
from google.api_core.exceptions import GoogleAPICallError


class GoogleCloudKMSSigner:
    def __init__(
        self,
        key_name: Optional[str] = None,
    ) -> None:
        self.client = kms_v1.KeyManagementServiceClient()
        self.key_name = key_name or os.environ.get("GCP_KMS_KEY_NAME")
        if not self.key_name:
            raise ValueError("Missing Google Cloud KMS key name. Set GCP_KMS_KEY_NAME or pass key_name.")

    def sign(self, message: bytes) -> bytes:
        digest = kms_v1.Digest()
        digest.sha256 = __import__("hashlib").sha256(message).digest()
        try:
            response = self.client.asymmetric_sign(
                request={"name": self.key_name, "digest": digest}
            )
            return response.signature
        except GoogleAPICallError as e:
            raise RuntimeError(f"Google Cloud KMS signing failed: {e}") from e

    def verify(self, message: bytes, signature: bytes) -> bool:
        public_key = self.client.get_public_key(request={"name": self.key_name})
        pem = public_key.pem
        if not pem:
            raise RuntimeError("Google Cloud KMS did not return a public key.")

        try:
            from cryptography.hazmat.primitives import hashes, serialization
            from cryptography.hazmat.primitives.asymmetric import padding, ec, rsa
            from cryptography.exceptions import InvalidSignature
        except ImportError as e:
            raise ImportError("cryptography is required for verification.") from e

        pub = serialization.load_pem_public_key(pem.encode("utf-8"))

        try:
            if isinstance(pub, rsa.RSAPublicKey):
                pub.verify(signature, message, padding.PKCS1v15(), hashes.SHA256())
            elif isinstance(pub, ec.EllipticCurvePublicKey):
                pub.verify(signature, message, ec.ECDSA(hashes.SHA256()))
            else:
                raise TypeError(f"Unsupported key type: {type(pub).__name__}")
            return True
        except InvalidSignature:
            return False

    def sign_json(self, payload: dict) -> dict:
        message = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
        signature = self.sign(message)
        return {
            "payload": payload,
            "signature_b64": __import__("base64").b64encode(signature).decode("ascii"),
        }

    def verify_json(self, signed_payload: dict) -> bool:
        payload = signed_payload["payload"]
        signature_b64 = signed_payload["signature_b64"]
        message = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
        signature = __import__("base64").b64decode(signature_b64)
        return self.verify(message, signature)
